import { ref, nextTick } from 'vue'
const solutions = ref(false)
const answers = {
  1: ['Einmaliges Vorhaben', 'Zeitlich begrenzt', 'Klar definiertes Ziel', 'Begrenzte Ressourcen'],
  4: ['Ursachen des Problems untersuchen', 'Bedürfnisse der Betroffenen verstehen'],
  5: ['Briefing: Der Auftraggeber erklärt, was er benötigt.', 'Rebriefing: Der Auftragnehmer fasst sein Verständnis zusammen', 'und klärt offene Fragen.', ''],
  6: ['Lastenheft: Was der Auftraggeber möchte.', 'Pflichtenheft: Wie der Auftragnehmer die Anforderungen', 'konkret umsetzen wird.', ''],
  8: ['Möglichst viele unterschiedliche und kreative', 'Lösungsansätze entwickeln.', ''],
  9: ['Zunächst möglichst viele Ideen sammeln,', 'ohne sie sofort zu bewerten.', ''],
