  11: ['Originalität', 'Nutzen', 'Umsetzbarkeit'],
  12: ['Eine neue oder deutlich verbesserte Lösung', 'mit echtem Mehrwert.'],
  13: ['Analyse der Ideen', 'Auswahl und Entscheidung', 'Optimierung']
}

const exporting = ref(false)
const exportError = ref('')
async function downloadPdf() {
  if (exporting.value) return
  exporting.value = true
  exportError.value = ''
  try {
    solutions.value = false
    await nextTick()
    await document.fonts.ready
    const [{ default: html2canvas }, { jsPDF }] = await Promise.all([import('html2canvas'), import('jspdf')])
    const pages = Array.from(document.querySelectorAll('.exam .paper'))
    const pdf = new jsPDF({ unit: 'mm', format: 'a4', compress: true })
    for (const [index, page] of pages.entries()) {
      const canvas = await html2canvas(page, { scale: 2, backgroundColor: '#ffffff', useCORS: true, windowWidth: Math.max(document.documentElement.clientWidth, 850) })
      if (index) pdf.addPage()
      pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, 0, 210, 297)
    }
    pdf.save('Klassenarbeit_01_3TGG2.pdf')
  } catch (error) {
    exportError.value = 'Die PDF konnte nicht erstellt werden. Bitte erneut versuchen.'
  } finally {
    exporting.value = false
  }
}
</script>
